#!/usr/bin/env node
// Fetches a YouTube video's metadata and caption transcript with no dependencies.
//
// Usage:
//   node fetch-transcript.mjs <youtube-url-or-id> <out-dir> [--lang en,hi]
//
// Writes into <out-dir>:
//   video.json       metadata (title, channel, description, duration, publish date, chapters)
//   transcript.json  { method, language, isAutoGenerated, segments: [{start, dur, text}] }
//   transcript.txt   readable transcript, one [mm:ss] block per ~30 seconds
//
// Methods tried, in order (each is a normal public request, no auth bypass):
//   1. InnerTube player API with the ANDROID client (what the YouTube app uses;
//      its caption URLs don't need a proof-of-origin token the way web ones now do)
//   2. captionTracks embedded in the watch page's ytInitialPlayerResponse
// Exit codes: 0 ok, 1 usage/network error, 2 video has no retrievable captions
// (the skill then falls back to reading the transcript panel in a browser).

import fs from 'node:fs';
import path from 'node:path';

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36';
const ANDROID_CLIENT = { clientName: 'ANDROID', clientVersion: '20.10.38', androidSdkVersion: 34, hl: 'en', gl: 'US' };

function parseVideoId(input) {
  if (/^[\w-]{11}$/.test(input)) return input;
  let u;
  try { u = new URL(input); } catch { return null; }
  if (u.hostname === 'youtu.be') return u.pathname.slice(1, 12);
  if (u.searchParams.get('v')) return u.searchParams.get('v');
  const m = u.pathname.match(/\/(?:shorts|embed|live|v)\/([\w-]{11})/);
  return m ? m[1] : null;
}

function decodeEntities(s) {
  return s
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)));
}

// Pulls a JSON object literal assigned to `varName` out of an HTML page by brace matching,
// because a regex can't reliably find the end of a large nested object.
function extractJsonVar(html, varName) {
  const idx = html.indexOf(varName);
  if (idx === -1) return null;
  const start = html.indexOf('{', idx);
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < html.length; i++) {
    const ch = html[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') inStr = true;
    else if (ch === '{') depth++;
    else if (ch === '}' && --depth === 0) {
      try { return JSON.parse(html.slice(start, i + 1)); } catch { return null; }
    }
  }
  return null;
}

async function fetchText(url, init = {}) {
  const res = await fetch(url, { ...init, headers: { 'User-Agent': UA, 'Accept-Language': 'en-US,en;q=0.9', ...(init.headers || {}) } });
  if (!res.ok) throw new Error(`HTTP ${res.status} for ${url.split('?')[0]}`);
  return res.text();
}

function pickTrack(tracks, langs) {
  if (!tracks?.length) return null;
  const manual = tracks.filter(t => t.kind !== 'asr');
  const auto = tracks.filter(t => t.kind === 'asr');
  for (const pool of [manual, auto]) {
    for (const lang of [...langs, 'en']) {
      const hit = pool.find(t => t.languageCode === lang || t.languageCode.startsWith(lang + '-'));
      if (hit) return hit;
    }
  }
  // Nothing in a preferred language or English: take the first manual track, else the first auto one.
  return manual[0] || auto[0];
}

// Handles both caption XML formats YouTube serves: legacy <text start dur> and srv3 <p t d>.
function parseCaptionXml(xml) {
  const segs = [];
  for (const m of xml.matchAll(/<text start="([\d.]+)"(?: dur="([\d.]+)")?[^>]*>([\s\S]*?)<\/text>/g)) {
    segs.push({ start: +m[1], dur: +(m[2] || 0), text: m[3] });
  }
  if (!segs.length) {
    for (const m of xml.matchAll(/<p t="(\d+)"(?: d="(\d+)")?[^>]*>([\s\S]*?)<\/p>/g)) {
      segs.push({ start: +m[1] / 1000, dur: +(m[2] || 0) / 1000, text: m[3].replace(/<[^>]+>/g, '') });
    }
  }
  return segs
    .map(s => ({ ...s, text: decodeEntities(decodeEntities(s.text)).replace(/\s+/g, ' ').trim() }))
    .filter(s => s.text);
}

async function tracksViaInnertube(videoId, apiKey) {
  const url = `https://www.youtube.com/youtubei/v1/player${apiKey ? `?key=${apiKey}` : ''}`;
  const body = JSON.stringify({ context: { client: ANDROID_CLIENT }, videoId });
  const json = JSON.parse(await fetchText(url, { method: 'POST', body, headers: { 'Content-Type': 'application/json' } }));
  return json?.captions?.playerCaptionsTracklistRenderer?.captionTracks || [];
}

function fmtTime(sec) {
  const s = Math.floor(sec);
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60;
  const mm = String(m).padStart(h ? 2 : 1, '0'), ss = String(r).padStart(2, '0');
  return h ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
}

function toReadable(segments, blockSeconds = 30) {
  const blocks = [];
  let cur = null;
  for (const s of segments) {
    if (!cur || s.start - cur.start >= blockSeconds) {
      cur = { start: s.start, parts: [] };
      blocks.push(cur);
    }
    cur.parts.push(s.text);
  }
  return blocks.map(b => `[${fmtTime(b.start)}] ${b.parts.join(' ')}`).join('\n\n') + '\n';
}

// Chapters are written as "0:00 Intro" lines in the description.
function parseChapters(description) {
  const out = [];
  for (const line of (description || '').split('\n')) {
    const m = line.match(/^\s*\(?((?:\d{1,2}:)?\d{1,2}:\d{2})\)?\s*[-–—:]?\s*(.+)$/);
    if (m) out.push({ time: m[1], title: m[2].trim() });
  }
  return out.length >= 2 ? out : [];
}

async function main() {
  const args = process.argv.slice(2);
  const langIdx = args.indexOf('--lang');
  const langs = langIdx >= 0 ? args.splice(langIdx, 2)[1].split(',') : ['en'];
  const [input, outDir] = args;
  if (!input || !outDir) {
    console.error('Usage: node fetch-transcript.mjs <youtube-url-or-id> <out-dir> [--lang en,hi]');
    process.exit(1);
  }
  const videoId = parseVideoId(input);
  if (!videoId) { console.error(`Could not parse a video id from: ${input}`); process.exit(1); }
  fs.mkdirSync(outDir, { recursive: true });
  const watchUrl = `https://www.youtube.com/watch?v=${videoId}`;

  // Watch page: metadata, API key, and fallback caption tracks. The CONSENT cookie
  // skips the EU cookie interstitial, which otherwise replaces the whole page.
  const html = await fetchText(watchUrl, { headers: { Cookie: 'CONSENT=YES+1; SOCS=CAI' } });
  const apiKey = (html.match(/"INNERTUBE_API_KEY":"([^"]+)"/) || [])[1];
  const player = extractJsonVar(html, 'ytInitialPlayerResponse') || {};
  const vd = player.videoDetails || {};
  const mf = player.microformat?.playerMicroformatRenderer || {};

  let oembed = {};
  try { oembed = JSON.parse(await fetchText(`https://www.youtube.com/oembed?url=${encodeURIComponent(watchUrl)}&format=json`)); } catch { /* optional */ }

  const video = {
    videoId,
    url: watchUrl,
    title: vd.title || oembed.title || null,
    channel: vd.author || oembed.author_name || null,
    channelUrl: oembed.author_url || null,
    description: vd.shortDescription || '',
    lengthSeconds: vd.lengthSeconds ? Number(vd.lengthSeconds) : null,
    publishDate: mf.publishDate || mf.uploadDate || null,
    category: mf.category || null,
    keywords: vd.keywords || [],
    viewCount: vd.viewCount ? Number(vd.viewCount) : null,
    chapters: parseChapters(vd.shortDescription),
    playability: player.playabilityStatus?.status || null,
    fetchedAt: new Date().toISOString(),
  };
  fs.writeFileSync(path.join(outDir, 'video.json'), JSON.stringify(video, null, 2));
  console.log(`Video: ${video.title} — ${video.channel} (${video.lengthSeconds ? fmtTime(video.lengthSeconds) : '?'})`);

  const attempts = [
    ['innertube-android', () => tracksViaInnertube(videoId, apiKey)],
    ['watch-page', async () => player?.captions?.playerCaptionsTracklistRenderer?.captionTracks || []],
  ];
  const errors = [];
  for (const [method, getTracks] of attempts) {
    try {
      const tracks = await getTracks();
      const track = pickTrack(tracks, langs);
      if (!track) { errors.push(`${method}: no caption tracks`); continue; }
      const xml = await fetchText(track.baseUrl.replace(/&fmt=[^&]+/, ''));
      const segments = parseCaptionXml(xml);
      if (!segments.length) { errors.push(`${method}: caption file was empty`); continue; }

      const transcript = {
        videoId, method,
        language: track.languageCode,
        isAutoGenerated: track.kind === 'asr',
        availableLanguages: tracks.map(t => `${t.languageCode}${t.kind === 'asr' ? ' (auto)' : ''}`),
        segments,
      };
      fs.writeFileSync(path.join(outDir, 'transcript.json'), JSON.stringify(transcript, null, 2));
      fs.writeFileSync(path.join(outDir, 'transcript.txt'), toReadable(segments));
      const words = segments.reduce((n, s) => n + s.text.split(/\s+/).length, 0);
      console.log(`Transcript: ${segments.length} segments, ~${words} words, lang=${track.languageCode}${transcript.isAutoGenerated ? ' (auto-generated)' : ''}, via ${method}`);
      if (!langs.some(l => track.languageCode.startsWith(l))) {
        console.log(`NOTE: no track in [${langs}] — used ${track.languageCode}. Available: ${transcript.availableLanguages.join(', ')}`);
      }
      return;
    } catch (e) {
      errors.push(`${method}: ${e.message}`);
    }
  }
  console.error('No transcript retrieved:\n  ' + errors.join('\n  '));
  console.error('Metadata was still saved to video.json. Fall back to the browser transcript panel (see SKILL.md, step 2).');
  process.exit(2);
}

main().catch(e => { console.error(e.message || e); process.exit(1); });
